$a=access_service();$r=$a->repo;
if((int)$r->run('SELECT @@port')->fetchColumn()!==3307||$r->run('SELECT DATABASE()')->fetchColumn()!=='tivoli_auth_test'||$r->run('SELECT marker FROM security_test_marker')->fetchColumn()!=='synthetic-auth-only-v1')exit(2);
if(!class_exists(HousekeepingService::class))throw new RuntimeException('Approved housekeeping service missing');

$n=0;$tag=bin2hex(random_bytes(6));$clock='2034-11-14 14:00:00';$owner=(int)$r->run("SELECT id FROM users WHERE email='admin@example.invalid'")->fetchColumn();putenv('TIVOLI_FINANCE_OWNER_USER_ID='.$owner);
function hk():string{return bin2hex(random_bytes(16));}
function ha(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);$n++;echo "PASS $label\n";}
function hd(callable $f,string $label):void{try{$f();}catch(Throwable $e){ha(true,$label);return;}throw new RuntimeException('Expected denial '.$label);}
function hu(string $role='clerk'):int{global $r;$r->run('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)',['Synthetic housekeeper',hk().'@example.invalid',password_hash('Synthetic Housekeeping Passphrase 123!',PASSWORD_BCRYPT),$role]);$id=(int)$r->db->lastInsertId();$r->run('INSERT INTO security_accounts(user_id,must_change_password) VALUES(?,0)',[$id]);$r->run('INSERT INTO security_user_roles SELECT ?,id FROM security_roles WHERE name=?',[$id,$role]);return $id;}
$staff=hu();$other=hu();$admin=hu('admin');$s=new HousekeepingService($a,$clock);$legacy=new \Tivoli\Service\StayService($a,$clock);
function hrm():int{global $r;$r->run("INSERT INTO rooms(name,type,rate,status) VALUES(?,'Standard',100,'dirty')",['Synthetic housekeeping '.hk()]);$id=(int)$r->db->lastInsertId();$r->run("INSERT INTO stay_room_settings(room_id,ready_state) VALUES(?,'cleaning')",[$id]);return $id;}
function hc(int $actor,string $action,array $in=[],?string $key=null):array{global $s;return $s->execute($actor,$action,$in,$key??hk());}
function hv(int $actor,int $id):array{global $s;return ['id'=>(string)$id,'version'=>$s->detail($actor,$id)['version']];}
function hs(int $actor,int $room):int{global $s;return hc($actor,'start',['room_id'=>(string)$room,'room_token'=>$s->room($actor,$room)['token']])['id'];}
function hdone(int $id,int $actor):array{global $s;$c=$s->detail($actor,$id);return array_merge(...array_map(fn($section)=>array_column($section['items'],'id'),$c['root']['data']['cleaning']['sections']));}
function hcomplete(int $actor,int $id):void{global $s;$sections=$s->detail($actor,$id)['root']['data']['cleaning']['sections'];foreach($sections as $i=>$section)hc($actor,'progress',hv($actor,$id)+['direction'=>$i===count($sections)-1?'complete':'next','done'=>json_encode(hdone($id,$actor)),'verified'=>'1','comment'=>'Synthetic completed checklist']);}
function hinspect(int $actor,int $id,string $decision='release',?array $results=null):array{global $s;$c=$s->detail($actor,$id);$all=array_merge(...array_map(fn($section)=>array_column($section['items'],'id'),$c['root']['data']['inspection']['sections']));$results??=array_fill_keys($all,'pass');return hc($actor,'inspect',hv($actor,$id)+['results'=>json_encode($results),'decision'=>$decision,'verified'=>'1','comment'=>'Synthetic inspection']);}

function hjob(int $who,string $action,array $input,string $service='housekeeping',?string $key=null):array{global $clock;return ['actor'=>$who,'action'=>$action,'input'=>$input,'service'=>$service,'clock'=>$clock,'key'=>$key??hk()];}
function hrace(array $jobs):array{$base=dirname(__DIR__,2).'/.local-setup/housekeeping-race-'.hk();$ps=[];foreach($jobs as $i=>$j){$p=proc_open([PHP_BINARY,__DIR__.'/housekeeping_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($j+['barrier'=>$base,'worker'=>$i]));fclose($pipes[0]);$ps[]=[$p,$pipes];}$until=microtime(true)+15;while(!is_file($base.'.ready0')||!is_file($base.'.ready1')){if(microtime(true)>$until)throw new RuntimeException('Barrier timeout');usleep(10000);}file_put_contents($base.'.go','go');$out=[];foreach($ps as [$p,$pipes]){$v=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed');$out[]=json_decode($v,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($base.$suffix);return $out;}
function hlast(int $id,int $who):array{global $s;$sections=$s->detail($who,$id)['root']['data']['cleaning']['sections'];for($i=0;$i<count($sections)-1;$i++)hc($who,'progress',hv($who,$id)+['direction'=>'next','done'=>json_encode(hdone($id,$who))]);return hv($who,$id)+['direction'=>'complete','done'=>json_encode(hdone($id,$who)),'verified'=>'1'];}
function hi(int $id,int $who):array{global $s;$c=$s->detail($who,$id);$keys=array_merge(...array_map(fn($sec)=>array_column($sec['items'],'id'),$c['root']['data']['inspection']['sections']));return hv($who,$id)+['results'=>json_encode(array_fill_keys($keys,'pass')),'decision'=>'release','verified'=>'1'];}
$room=hrm();$input=['room_id'=>(string)$room,'room_token'=>$s->room($staff,$room)['token']];$out=hrace([hjob($staff,'start',$input),hjob($other,'start',$input)]);ha(count(array_filter($out,fn($x)=>$x['ok']))===1,'Two simultaneous cleaners create one assignment');
$room=hrm();$id=hs($staff,$room);$input=hlast($id,$staff);$job=hjob($staff,'progress',$input);$out=hrace([$job,$job]);ha(count(array_filter($out,fn($x)=>$x['ok']))===2&&(int)$r->run("SELECT COUNT(*) FROM finance_events WHERE target_type='housekeeping' AND target_id=? AND kind='hk_completed'",[(string)$id])->fetchColumn()===1,'Identical cleaning-completion retries record once');
$room=hrm();$id=hs($staff,$room);hcomplete($staff,$id);$out=hrace([hjob($other,'inspect',hi($id,$other)),hjob($owner,'inspect',hi($id,$owner))]);ha(count(array_filter($out,fn($x)=>$x['ok']))===1,'Two independent inspectors cannot release twice');
$room=hrm();$id=hs($staff,$room);hcomplete($staff,$id);hc($staff,'request_exception',hv($staff,$id)+['reason'=>'No cover']);$out=hrace([hjob($owner,'decide_exception',hv($owner,$id)+['decision'=>'approve','reason'=>'One inspection only']),hjob($other,'inspect',hi($id,$other))]);if($s->detail($other,$id)['status']==='inspection')hinspect($other,$id);$c=$s->detail($owner,$id);ha($c['status']==='released'&&$c['exception']['status']==='closed-unused'&&count(array_filter($out,fn($x)=>$x['ok']))===1,'Authorization versus independent inspection cannot leave a reusable grant');
$room=hrm();$id=hs($staff,$room);hcomplete($staff,$id);$out=hrace([hjob($other,'inspect',hi($id,$other)),hjob($owner,'fault',['room_id'=>(string)$room,'priority'=>'Critical','owner'=>'Synthetic repairs','reason'=>'Unsafe wiring'],'stay')]);$facts=$s->room($owner,$room)['facts'];ha($out[1]['ok']&&$facts['blocked']&&$facts['ready_state']==='blocked','Critical fault versus release leaves room blocked');
$room=hrm();$id=hs($staff,$room);hcomplete($staff,$id);$guest=['room_id'=>(string)$room,'guest_name'=>'Synthetic housekeeping race guest','phone'=>'0000','gender'=>'Male','nationality'=>'Ghana','stay_type'=>'overnight','amount'=>'100.00','expected_rate'=>'100.00','payment_type'=>'cash','identity_verified'=>'1','payment_attested'=>'1','room_checked'=>'1'];$out=hrace([hjob($other,'inspect',hi($id,$other)),hjob($staff,'checkin',$guest,'stay')]);$facts=$s->room($owner,$room)['facts'];ha($out[0]['ok']&&($out[1]['ok']?$facts['occupied']&&$facts['status']==='occupied':!$facts['occupied']&&$facts['ready_state']==='ready'),'Check-in versus release has one valid physical ordering');
$room=hrm();$id=hs($staff,$room);hcomplete($staff,$id);hc($staff,'request_exception',hv($staff,$id)+['reason'=>'No cover']);hc($owner,'decide_exception',hv($owner,$id)+['decision'=>'approve','reason'=>'One attempt authorized']);hinspect($staff,$id);$inspection=$s->detail($owner,$id)['followups'][0];$job=hjob($owner,'followup',hv($owner,$id)+['inspection_id'=>(string)$inspection['id'],'reason'=>'Evidence reviewed']);$out=hrace([$job,$job]);ha(count(array_filter($out,fn($x)=>$x['ok']))===2&&!$s->detail($owner,$id)['followups'],'Concurrent owner follow-up retries record one review');
$room=hrm();$id=hs($staff,$room);$input=hlast($id,$staff);$out=hrace([hjob($staff,'progress',$input),hjob($owner,'restart',hv($owner,$id)+['reason'=>'Assigned cleaner unavailable; owner starts fresh'])]);ha(count(array_filter($out,fn($x)=>$x['ok']))===1&&in_array($s->detail($owner,$id)['status'],['inspection','superseded'],true),'Owner restart versus completion preserves one valid assignment transition');
